const plural=(n:number,word:string)=>`${n} ${word}${n===1?'':'s'}`;
const structureFields=[['acidity','Acidity','Low','High'],['tannin','Tannin','Low','High'],['body','Body','Light','Full'],['finish','Finish','Short','Long']] as const;
